let zoom = 1;
let offset;

function preload() {
	theShader = loadShader('https://openprocessing.org/sketch/1624783/files/vert.glsl', 'frag.glsl');
	f = loadFont("https://openprocessing.org/sketch/1624783/files/Nunito-SemiBold.ttf");
}

function setup() {
	pixelDensity(2);
	canvas = createCanvas(1000, 1000, WEBGL);
	background(0);
	offset = createVector(0, 0);

	textGraphic = createGraphics(1000, 1000, WEBGL);
	textGraphic.pixelDensity(2);
	textGraphic.background(0);
	textGraphic.textFont(f);
	textGraphic.textSize(100);
	textGraphic.textAlign(CENTER, CENTER);
	textGraphic.fill("#ffffff");
	textGraphic.text("HIGH", 100, -100);
	textGraphic.text("VIBES", 100, 0);

	zoom = 0.45;
	offset.x = 50;
}

function draw() {
	var y = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-500) / min(1, windowWidth / windowHeight) + 500;
	var py = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-500) / min(1, windowWidth / windowHeight) + 500;

	theShader.setUniform("u_resolution", [width * 2, height * 2]);
	theShader.setUniform("u_time", millis() / 1000.0);
	theShader.setUniform("u_offset", [-offset.x * 2, offset.y * 2]);
	theShader.setUniform("u_zoom", 1.0 / zoom);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * 2, (height-y) * 2]);
	theShader.setUniform("u_text", textGraphic);

	noStroke();
	shader(theShader);
	rect(width * -0.5, height * -0.5, width, height);
}

